import math

class Shape:
    def area(self):
        return 0

class Rectangle(Shape):
    def __init__(self, w, h):
        self.w, self.h = w, h
    def area(self):
        return self.w * self.h

class Square(Rectangle):
    def __init__(self, s):
        super().__init__(s, s)

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):
        return math.pi * self.r ** 2

n = int(input())
shapes = []
for _ in range(n):
    parts = input().split()
    kind, nums = parts[0], [float(x) for x in parts[1:]]
    if kind == "rect":
        shapes.append(Rectangle(*nums))
    elif kind == "circle":
        shapes.append(Circle(*nums))
    else:
        shapes.append(Square(*nums))
for s in shapes:
    print(f"{s.area():.2f}")
print(f"Total: {sum(s.area() for s in shapes):.2f}")

