from dataclasses import dataclass

@dataclass
class Item:
    name: str
    price: float
    qty: int

    def total(self) -> float:
        return self.price * self.qty

n = int(input())
items: list[Item] = []
for _ in range(n):
    name, price, qty = input().split()
    items.append(Item(name, float(price), int(qty)))
for it in sorted(items, key=lambda i: (-i.total(), i.name)):
    print(f"{it.name} {it.total():.2f}")
print(f"Grand total: {sum(i.total() for i in items):.2f}")
